<?php

defined('ABSPATH') || exit;

$exampleId = str_repeat('Ab12', 32);
$messagesUrl = rest_url('tracking-pixel/v1/projects/PROJECT_ID/messages');
$eventsUrl = add_query_arg(['page' => 1, 'per_page' => 50], rest_url('tracking-pixel/v1/projects/PROJECT_ID/events'));
$summaryUrl = add_query_arg('external_id', $exampleId, rest_url('tracking-pixel/v1/projects/PROJECT_ID/summary'));
$show = static function (string $code): void {
    echo '<pre style="white-space:pre-wrap;overflow-wrap:anywhere;background:#fff;padding:12px;border:1px solid #c3c4c7">' . esc_html($code) . '</pre>';
};
?>
<h2><?php esc_html_e('1. Create a Project and API Key', 'wordpress-tracking-pixel'); ?></h2>
<p><?php echo wp_kses_post(__('Open Tracking Pixel &rarr; Projects. Create a project and issue a read/write API key for your external email application. Store the key securely; it is shown once. A read-only key can retrieve reports but cannot register emails. To rotate a key, issue a replacement, update your application, and revoke the old key.', 'wordpress-tracking-pixel')); ?></p>
<p><?php esc_html_e('Use HTTPS. Send API keys only in the Authorization header, never in emails, browser code, or URLs. Project IDs identify a project but do not grant API access.', 'wordpress-tracking-pixel'); ?></p>
<h2><?php esc_html_e('2. Understand the Identifiers', 'wordpress-tracking-pixel'); ?></h2>
<table class="widefat striped"><thead><tr><th><?php esc_html_e('Identifier', 'wordpress-tracking-pixel'); ?></th><th><?php esc_html_e('Format', 'wordpress-tracking-pixel'); ?></th><th><?php esc_html_e('Source', 'wordpress-tracking-pixel'); ?></th></tr></thead><tbody>
<tr><td><?php esc_html_e('Project ID', 'wordpress-tracking-pixel'); ?></td><td><?php esc_html_e('Exactly 10 characters, A-Z, a-z, 0-9', 'wordpress-tracking-pixel'); ?></td><td><?php esc_html_e('Generated by the plugin', 'wordpress-tracking-pixel'); ?></td></tr>
<tr><td><?php esc_html_e('External email ID', 'wordpress-tracking-pixel'); ?></td><td><?php esc_html_e('Exactly 128 characters, A-Z, a-z, 0-9, case-sensitive', 'wordpress-tracking-pixel'); ?></td><td><?php esc_html_e('Your application, or generated when omitted', 'wordpress-tracking-pixel'); ?></td></tr>
<tr><td><?php esc_html_e('Pixel token', 'wordpress-tracking-pixel'); ?></td><td><?php esc_html_e('64 random alphanumeric characters', 'wordpress-tracking-pixel'); ?></td><td><?php esc_html_e('Generated by the plugin; use the returned URL unchanged', 'wordpress-tracking-pixel'); ?></td></tr>
<tr><td><?php esc_html_e('API key', 'wordpress-tracking-pixel'); ?></td><td><?php esc_html_e('wtp_ followed by a selector and secret', 'wordpress-tracking-pixel'); ?></td><td><?php esc_html_e('Issued in WordPress admin; never embed in an email', 'wordpress-tracking-pixel'); ?></td></tr>
</tbody></table>
<p><?php esc_html_e('Use a different email ID for every recipient delivery. Reuse an ID only when referring to the same tracked message in the same project. Do not use email addresses as IDs.', 'wordpress-tracking-pixel'); ?></p>
<p><?php esc_html_e('A valid 128-character ID:', 'wordpress-tracking-pixel'); ?></p>
<?php $show($exampleId); ?>
<p><?php echo wp_kses_post(__('Invalid IDs include <code>email-123</code>, UUIDs with hyphens, IDs with spaces or underscores, and strings shorter or longer than 128 characters.', 'wordpress-tracking-pixel')); ?></p>
<p><?php esc_html_e('Example PHP generation in your sending application:', 'wordpress-tracking-pixel'); ?></p>
<?php $show('$alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";' . "\n" . '$externalId = "";' . "\n" . 'for ($position = 0; $position < 128; $position++) {' . "\n" . '    $externalId .= $alphabet[random_int(0, 61)];' . "\n" . '}'); ?>
<h2><?php esc_html_e('3. Register an Email', 'wordpress-tracking-pixel'); ?></h2>
<p><?php esc_html_e('Replace PROJECT_ID and YOUR_API_KEY below. To let the plugin generate an ID, send an empty JSON object:', 'wordpress-tracking-pixel'); ?></p>
<?php $show("curl --request POST '" . $messagesUrl . "' \\\n  --header 'Authorization: Bearer YOUR_API_KEY' \\\n  --header 'Content-Type: application/json' \\\n  --data '{}'"); ?>
<p><?php esc_html_e('To supply your own ID, use the same request with this JSON body:', 'wordpress-tracking-pixel'); ?></p>
<?php $show(wp_json_encode(['external_id' => $exampleId], JSON_PRETTY_PRINT)); ?>
<p><?php echo wp_kses_post(__('The response contains <code>project_id</code>, <code>external_id</code>, <code>tracking_url</code>, and <code>html</code>:', 'wordpress-tracking-pixel')); ?></p>
<?php $show(wp_json_encode([
    'project_id' => 'Ab3dE7fG9h', 'external_id' => $exampleId,
    'tracking_url' => home_url('/?wtp_pixel=Ab3dE7fG9h.') . str_repeat('T', 64),
    'html' => '<img src="' . home_url('/?wtp_pixel=Ab3dE7fG9h.') . str_repeat('T', 64) . '" width="1" height="1" alt="" style="border:0" />',
], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)); ?>
<p><?php esc_html_e('Keep the returned ID with your outgoing message record. Re-registering it returns the same link without resetting history. Omitting the ID again creates a new message. For reliable retries after a lost response, generate and persist your own ID before registration.', 'wordpress-tracking-pixel'); ?></p>
<h2><?php esc_html_e('4. Embed the Pixel', 'wordpress-tracking-pixel'); ?></h2>
<p><?php echo wp_kses_post(__('Insert the returned <code>html</code> string into the HTML body of the corresponding email before sending it. The exact format is:', 'wordpress-tracking-pixel')); ?></p>
<?php $show('<img src="RETURNED_TRACKING_URL" width="1" height="1" alt="" style="border:0" />'); ?>
<p><?php esc_html_e("Do not use display:none, embed an API key, or reuse another recipient's tracking URL. A plain-text-only email cannot load this image. This plugin does not send emails or track clicks.", 'wordpress-tracking-pixel'); ?></p>
<h2><?php esc_html_e('5. Retrieve Requests', 'wordpress-tracking-pixel'); ?></h2>
<?php $show("curl '" . $eventsUrl . "' \\\n  --header 'Authorization: Bearer YOUR_API_KEY'"); ?>
<p><?php echo wp_kses_post(__('Add <code>external_id</code> to filter one message, and <code>from</code>/<code>to</code> for inclusive UTC date boundaries such as <code>2026-10-30T00:00:00Z</code>. Page starts at 1; per_page is 1-100. Results are newest first; use event IDs to reconcile duplicates when new requests arrive during pagination.', 'wordpress-tracking-pixel')); ?></p>
<?php $show("curl '" . $summaryUrl . "' \\\n  --header 'Authorization: Bearer YOUR_API_KEY'"); ?>
<p><?php esc_html_e('Responses include request count, first/latest request timestamps in UTC, and (for events) the paginated event list. The total is the number of pixel requests, not the number of distinct readers. Dates are serialized as YYYY-MM-DDTHH:MM:SSZ. Invalid IDs, dates, and pagination return 400; invalid keys or scope return 401; production HTTP returns 403; storage failures return 500.', 'wordpress-tracking-pixel'); ?></p>
<p><?php esc_html_e('The WordPress Events tab uses the site date format, time format, and timezone from Settings > General. Its date filters use the site timezone, and its paginated table offers 10, 25, 50, or 100 events per page. API timestamps and API date filters remain UTC.', 'wordpress-tracking-pixel'); ?></p>
<p><?php esc_html_e('Omit external_id to retrieve events for the whole project. Events are paginated, with at most 100 per response; fetch all pages using X-WP-TotalPages. The summary endpoint returns the matching count and first/latest timestamps in one response, not a full export of messages or project settings.', 'wordpress-tracking-pixel'); ?></p>
<p><?php esc_html_e('Use last_days=5 on events or summary for the preceding five times 24 hours in UTC, ending at request time. Values must be whole numbers from 1 to 36500. It works for the whole project or with external_id. Do not combine last_days with from or to; that returns HTTP 400. Project retention still applies.', 'wordpress-tracking-pixel'); ?></p>
<?php $show("curl '" . add_query_arg(['last_days' => 5, 'per_page' => 100, 'page' => 1], rest_url('tracking-pixel/v1/projects/PROJECT_ID/events')) . "' \\\n  --header 'Authorization: Bearer YOUR_API_KEY'"); ?>
<?php $show("curl '" . add_query_arg('last_days', 5, rest_url('tracking-pixel/v1/projects/PROJECT_ID/summary')) . "' \\\n  --header 'Authorization: Bearer YOUR_API_KEY'"); ?>
<p><?php esc_html_e('Time-filtered responses include date_range.from and date_range.to as ISO UTC timestamps. For consistent pagination, reuse those resolved values as from and to on subsequent pages and omit last_days. Otherwise the relative time window is recalculated on each request. Date boundaries are inclusive.', 'wordpress-tracking-pixel'); ?></p>
<h2><?php esc_html_e('6. Retention and Reliability', 'wordpress-tracking-pixel'); ?></h2>
<p><?php esc_html_e('Each project defaults to indefinite event history. Optional rolling 90-day retention hides expired events immediately and deletes them through hourly WordPress scheduled cleanup. Message IDs and links remain valid indefinitely, so an email opened years later can record another request. Switching back to indefinite cannot restore deleted events.', 'wordpress-tracking-pixel'); ?></p>
<p><?php echo wp_kses_post(__('WP-Cron depends on site traffic. For strict physical deletion deadlines, configure server cron to run <code>wp cron event run --due-now</code>. Backups and external logs need their own retention policies.', 'wordpress-tracking-pixel')); ?></p>
<p><?php echo wp_kses_post(__('Exclude every request with the <code>wtp_pixel</code> query parameter from CDN, reverse-proxy, and WordPress page caches. Exclude authenticated API routes from caching too. If your server strips Authorization headers, configure it to forward them to PHP.', 'wordpress-tracking-pixel')); ?></p>
<p><?php esc_html_e('Every received valid GET is recorded, including repeat requests. HEAD requests are not recorded. Apple Mail Privacy Protection, image proxies, security scanners, disabled images, and email-client caching can create or suppress requests. These events cannot prove that a person read an email.', 'wordpress-tracking-pixel'); ?></p>
<h2><?php esc_html_e('7. Privacy and Updates', 'wordpress-tracking-pixel'); ?></h2>
<p><?php esc_html_e('The plugin stores external IDs and request timestamps, not recipient addresses, IP addresses, user agents, or tracking cookies. Pseudonymous tracking can still be subject to privacy law and consent requirements. Server/CDN logs may collect additional data independently.', 'wordpress-tracking-pixel'); ?></p>
<p><?php esc_html_e("Stable GitHub Releases appear through WordPress's normal update checks. Detection is periodic, not immediate; automatic installation depends on your site's automatic-update settings. No separate updater plugin or GitHub token is required for public releases.", 'wordpress-tracking-pixel'); ?></p>
<p><?php esc_html_e('Deactivating or uninstalling the plugin preserves its data. Deleting a project explicitly in admin permanently deletes its keys, messages, and events.', 'wordpress-tracking-pixel'); ?></p>
<h2><?php esc_html_e('8. Test Your Live API', 'wordpress-tracking-pixel'); ?></h2>
<p><?php esc_html_e('The optional command-line tester requires Node.js 22 or newer and a project API key. Run it only against a site and project you are authorized to test. Download the generic script and run the commands below from its directory.', 'wordpress-tracking-pixel'); ?></p>
<p><a class="button" href="<?php echo esc_url(plugins_url('tools/live-test.mjs', WTP_FILE)); ?>" download="live-test.mjs"><?php esc_html_e('Download live API tester', 'wordpress-tracking-pixel'); ?></a></p>
<p><?php esc_html_e('Enter the API namespace URL when prompted, then the project ID and API key. The key prompt is hidden. Configuration stays in environment variables; never save live credentials, site details, or response data in project files or shared commands.', 'wordpress-tracking-pixel'); ?></p>
<?php $show(rest_url('tracking-pixel/v1')); ?>
<?php $show("read -r -p 'HTTPS API namespace URL: ' WTP_LIVE_API_URL\nread -r -p 'Project ID: ' WTP_LIVE_PROJECT_ID\nread -r -s -p 'Project API-Key: ' WTP_LIVE_API_KEY\nprintf '\\n'\nexport WTP_LIVE_API_URL WTP_LIVE_PROJECT_ID WTP_LIVE_API_KEY\nnode live-test.mjs"); ?>
<p><?php esc_html_e('The default is read-only: it checks authentication and summary retrieval without creating data. The tester prints only check results, not API keys, message IDs, tracking URLs, or raw responses.', 'wordpress-tracking-pixel'); ?></p>
<p><?php esc_html_e('For a dedicated test project, the optional write test creates two messages and two pixel events. It checks registration, repeated pixel requests, pagination, and summaries. Those records remain in the project for inspection; the tester does not delete projects or revoke keys.', 'wordpress-tracking-pixel'); ?></p>
<?php $show("WTP_LIVE_ALLOW_WRITES=1 node live-test.mjs\nunset WTP_LIVE_API_URL WTP_LIVE_PROJECT_ID WTP_LIVE_API_KEY"); ?>
<p><?php esc_html_e('Revoke disposable API keys after testing. HTTPS is required; redirects are not followed and credentials are never forwarded to another origin. Hosting logs have their own retention policies.', 'wordpress-tracking-pixel'); ?></p>